SELECT c.id, c.doc_id AS "docId", c.kb_id AS "kbId", c.content, c.page_no AS "pageNo",
       d.file_name AS "fileName"
  FROM kb_chunk c JOIN kb_document d ON d.id = c.doc_id
 WHERE c.kb_id IN

    #{id}

   AND d.deleted = FALSE
   AND d.parse_status = 'SUCCESS'
   AND d.chunk_status IN ('INDEXED', 'PARTIAL')
   AND (

        #{clause}

   )
 ORDER BY c.id DESC
 LIMIT #{limit}
